<template>
  <div class="s-page"><div class="s-page-heading"><div><p class="s-eyebrow">03 / EVALUATE</p><h1>让每一份合成数据，有据可依。</h1><p>用独立留出数据检验分布、结构与下游效用，把结果变成可审查的交付物。</p></div><button v-if="report" class="s-button primary" @click="studio.download(studio.generation.id)"><el-icon><Download /></el-icon>导出数据与报告</button></div>
    <JobStatus :job="studio.generation" />
    <div v-if="!report" class="s-panel s-empty"><el-icon><CircleCheck /></el-icon><h3>等待一份可检验的生成实验</h3><p>完成数据生成后，评估结果会在这里显示。</p><RouterLink class="s-button primary" to="/generate">前往数据生成 →</RouterLink></div>
    <template v-else><div class="s-panel s-report-header"><div><span class="s-eyebrow">DATA QUALITY REPORT</span><h2>{{ studio.selected?.name }}</h2><p>实验 {{ studio.generation.id.slice(0, 8) }} · {{ date(studio.generation.created) }} · 鼠先知引擎</p></div><label class="s-field">生成实验<select :value="studio.generation.id" @change="studio.generationId = $event.target.value"><option v-for="job in studio.generations.filter(j => j.status === 'completed')" :key="job.id" :value="job.id">{{ job.id.slice(0, 8) }} · {{ job.config.count }} 个窗口 · {{ date(job.created) }}</option></select></label></div>
    <div class="s-report-context"><span><el-icon><Lock /></el-icon>时间留出评估</span><span>保留区间不参与结构发现与生成</span><span>比较值使用训练尺度归一化</span></div>
    <section class="s-metric-grid"><article v-for="metric in metrics" :key="metric.name" class="s-panel s-metric"><span>{{ metric.name }}</span><strong>{{ metric.value }}</strong><small>{{ metric.help }}</small></article></section>
    <div class="s-section-heading"><h2>分布与时间结构</h2><label class="s-inline-field">评估变量<select v-model.number="channel"><option v-for="(name, index) in result.columns" :key="name" :value="index">{{ name }}</option></select></label></div><div class="s-two-col"><section class="s-panel"><h3>数值分布</h3><StudioChart :option="histogram" :height="240" /><p class="s-chart-note">归一化值的频数占比；比较边缘分布。</p></section><section class="s-panel"><h3>时间依赖</h3><StudioChart :option="acf" :height="240" /><p class="s-chart-note">窗口内自相关；横轴为滞后采样点数。</p></section><section class="s-panel"><h3>频谱结构</h3><StudioChart :option="spectrum" :height="240" /><p class="s-chart-note">去均值后的平均功率谱，占比归一化；横轴为频率序号。</p></section><section class="s-panel"><h3>模式覆盖</h3><StudioChart :option="coverage" :height="240" /><p class="s-chart-note">按训练结构归属后的占比。{{ studio.generation.config.target !== null ? '本实验定向扩充指定模式，总体分布差异需结合该目的解释。' : '覆盖训练模式并不代表捕获了所有未知模式。' }}</p></section></div>
    <section class="s-panel"><div class="s-section-heading"><div><span class="s-eyebrow">DOES THE DATA HELP?</span><h2>回到真实数据，检验下游效用。</h2></div><span class="s-pill">预测作为评估工具</span></div><p class="s-muted">相同预测任务、相同留出数据，对比三种训练数据来源。误差越低越好。</p><div class="s-utility-grid"><article><span>真实数据训练 · TRTR</span><strong>{{ number(report.utility.trtr_mae) }}</strong><small>作为参照的标准化 MAE</small></article><article><span>合成数据训练 · TSTR</span><strong>{{ number(report.utility.tstr_mae) }}</strong><small>在真实留出集上测量</small></article><article class="s-utility-augmented"><span>真实 + 合成数据训练</span><strong>{{ number(report.utility.augmented_mae) }}</strong><small>{{ gainText }}</small></article></div><div class="s-info-note"><el-icon><InfoFilled /></el-icon><p>这是单次时间留出下的探索性比较，不代表统计显著性或生产性能。重复查看同一留出集可能产生选择偏差，确认性实验需要新的测试数据。持续值参照误差：{{ number(report.utility.persistence_mae) }}。</p></div></section>
    <div class="s-two-col"><section class="s-panel"><span class="s-eyebrow">PRIVACY & ORIGINALITY</span><h2>检查复制风险</h2><div class="s-key-values"><div><span>近乎相同的训练窗口</span><strong>{{ percent(report.privacy.exact_duplicate_rate) }}</strong></div><div><span>更接近训练数据的窗口</span><strong>{{ percent(report.privacy.close_to_train_rate) }}</strong></div><div><span>最近训练邻居距离中位数</span><strong>{{ number(report.privacy.nearest_train_rms_median) }}</strong></div><div><span>成员推断评估</span><strong class="s-amber">未评估</strong></div><div><span>隐私认证</span><strong class="s-amber">未提供</strong></div></div><p class="s-chart-note">近邻距离仅用于诊断，不构成匿名性、差分隐私或数据安全的证明。</p></section><section class="s-panel s-export-panel"><span class="s-eyebrow">TAKE YOUR EVIDENCE WITH YOU</span><h2>数据与证据，一起交付。</h2><p>下载包含生成窗口、质量报告和实验清单的数据包，继续你的建模与验证工作。</p><div class="s-file-row"><el-icon><Document /></el-icon><span>synthetic.csv<small>独立窗口与变量值</small></span><span>CSV</span></div><div class="s-file-row"><el-icon><DocumentChecked /></el-icon><span>report.html / report.json<small>可阅读、可处理的质量报告</small></span><span>REPORT</span></div><div class="s-file-row"><el-icon><Tickets /></el-icon><span>manifest.json<small>来源、实验配置与内容校验值</small></span><span>PROVENANCE</span></div><button class="s-button primary full" @click="studio.download(studio.generation.id)"><el-icon><Download /></el-icon>下载完整数据包</button></section></div>
    <details class="s-panel s-report-notes"><summary>评估解释与使用边界</summary><ul><li v-for="note in report.warnings" :key="note">{{ note }}</li><li>目标模式扩充与整体分布匹配是不同目标，请结合所选生成目的解读指标。</li><li>没有单一的“可信分数”。请综合质量、效用和具体领域要求审查。</li></ul></details></template>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { Download, CircleCheck, Lock, InfoFilled, Document, DocumentChecked, Tickets } from '@element-plus/icons-vue'
import { useStudioStore } from '../../stores/studio'
import StudioChart from '../../components/studio/StudioChart.vue'
import JobStatus from '../../components/studio/JobStatus.vue'
import { base, lines, number, percent, date } from '../../components/studio/chartOptions'
const studio = useStudioStore(), channel = ref(0)
watch(() => studio.generation?.id, () => { channel.value = 0 })
const result = computed(() => studio.generation?.status === 'completed' ? studio.generation.result : null)
const report = computed(() => result.value?.evaluation)
const metrics = computed(() => report.value ? [{ name: '分布差异', value: number(report.value.wasserstein_mean), help: 'Wasserstein · 越低越接近' }, { name: '时间依赖差异', value: number(report.value.acf_mae), help: '自相关 MAE · 越低越接近' }, { name: '频谱差异', value: number(report.value.spectral_js_distance), help: 'JS 距离 · 越低越接近' }, { name: '模式覆盖率', value: percent(report.value.coverage.ratio), help: `${report.value.coverage.generated_modes} / ${report.value.coverage.training_modes} 个训练模式` }] : [])
const histogram = computed(() => { const h = report.value?.histograms[channel.value]; return lines(h ? [{ name: '源数据留出集', data: h.real, areaStyle: { opacity: 0.08 } }, { name: '合成数据', data: h.synthetic, itemStyle: { color: '#d19342' }, areaStyle: { opacity: 0.06 } }] : [], h?.centers.map(v => v.toFixed(2))) })
const acf = computed(() => lines(report.value ? [{ name: '源数据留出集', data: report.value.acf.real.map(v => v[channel.value]) }, { name: '合成数据', data: report.value.acf.synthetic.map(v => v[channel.value]) }] : [], report.value?.acf.real.map((_, i) => i + 1)))
const spectrum = computed(() => lines(report.value ? [{ name: '源数据留出集', data: report.value.spectrum.real.map(v => v[channel.value]) }, { name: '合成数据', data: report.value.spectrum.synthetic.map(v => v[channel.value]) }] : [], report.value?.spectrum.real.map((_, i) => i + 1)))
const coverage = computed(() => { const c = report.value?.coverage; const ratios = a => a.map(v => +(v / Math.max(a.reduce((s, x) => s + x, 0), 1) * 100).toFixed(1)); return { ...base, xAxis: { ...base.xAxis, boundaryGap: true, data: c?.train_counts.map((_, i) => `模式 ${i + 1}`) || [] }, yAxis: { ...base.yAxis, name: '占比 %' }, series: c ? [{ name: '源数据留出集', type: 'bar', barMaxWidth: 28, data: ratios(c.holdout_counts) }, { name: '合成数据', type: 'bar', barMaxWidth: 28, data: ratios(c.synthetic_counts) }] : [] } })
const gainText = computed(() => { const gain = report.value?.utility.augmentation_gain_percent; return gain == null ? '参照误差接近零，未计算相对变化' : gain >= 0 ? `本次误差下降 ${gain.toFixed(1)}% · 需进一步验证` : `本次误差增加 ${Math.abs(gain).toFixed(1)}% · 未观察到收益` })
</script>
